import MenuJson from "./menus.json";
import { useI18n } from 'vue-i18n';

export default {
  name: "Navbar",
  data() {
    return {
      menu: MenuJson,
      isLanguage: true,
    };
  },
  created() {},
  onUpdated() {
    changeLanguage();
  },
  methods: {
    changeLanguage(){
      if (isLanguage)
        useI18n().value = 'en';
      else
        useI18n().value = 'kh';
    }
  },
};
